        result[cp_cast_int(usize, 0)] = single;
        __result_moved = true;
        return result;
}

pub fn handleFileArray(global: *jsc.JSGlobalObject, elements: []const jsc.generated.SSLConfigSingleFile) !?[][*:0]u8 {
        if ((elements.len == 0)) {
            return null;
        }
        var result: bun.collections.ArrayListDefault(CString) = try .initCapacity(elements.len);
        _ = &result;
        errdefer {
        {
            for (cp_iter_slice(result.items())) |str_item| {
                _ = &str_item;
                _ = bun.freeSensitive(bun.default_allocator, std.mem.span(str_item));
            }
            _ = result.deinit();
        }
        }
        for (cp_mut_slice(&elements)) |*elem| {
            _ = &elem;
            _ = result.appendAssumeCapacity(try handleSingleFile(global, (switch ((elem.*).*) {
.string => |*val| SingleFileInput{ .string = val.get() },
.buffer => |*val| SingleFileInput{ .buffer = val.get() },
.file => |*val| SingleFileInput{ .file = val.get() },
})));
        }
        return try result.toOwnedSlice();
}

pub fn handleSingleFile(global: *jsc.JSGlobalObject, file: SingleFileInput) ![:0]const u8 {
        return (switch (file) {
.string => |s| s.toOwnedSliceZ(bun.default_allocator),
.buffer => |jsc_buffer| blk: {
        const buffer: jsc.ArrayBuffer = jsc_buffer.asArrayBuffer();
        break :blk try bun.default_allocator.dupeZ(u8, buffer.byteSlice());
},
.file => |blob| try readFromBlob(global, blob),
});
}
